ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);
for(const o of orbs){const pulse=1+Math.sin(t*4+o.p)*.18;ctx.shadowBlur=18;ctx.shadowColor='#ffdc8c';ctx.fillStyle='#ffe2a0';ctx.beginPath();ctx.arc(o.x,o.y,o.r*pulse,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#ffe5a066';ctx.lineWidth=1;ctx.beginPath();ctx.arc(o.x,o.y,o.r*2.15*pulse,0,Math.PI*2);ctx.stroke();}
