for(const b of document.querySelectorAll('.mobile-controls button')){const dir=b.dataset.dir;const down=e=>{e.preventDefault();touch[dir]=true;b.setPointerCapture?.(e.pointerId)};const up=e=>{e.preventDefault();touch[dir]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up);}
})();
</script>
